import { useEffect, useState } from "react";
import axios from "axios";
import "./Page.css";

function Jobs() {
  const [jobs, setJobs] = useState([]);
  const [year, setYear] = useState("");
  const [branch, setBranch] = useState("");
  const [category, setCategory] = useState(""); // Government vs Private
  const [loading, setLoading] = useState(false);

  // Initial Fetch: Load all Full-Time jobs
  useEffect(() => {
    fetchJobs();
  }, []);

  const fetchJobs = async () => {
    setLoading(true);
    try {
      // Ensuring we target Full-Time roles from your scraper data
      const response = await axios.get("http://localhost:5000/api/jobs?jobType=Full-time");
      setJobs(response.data);
    } catch (err) {
      console.error("Error fetching jobs:", err);
    }
    setLoading(false);
  };

  // Filter Fetch: Re-fetch based on dropdown selections
  const applyFilter = async () => {
    setLoading(true);
    const query = new URLSearchParams({
      jobType: "Full-time",
      batch: year,
      branch: branch,
      category: category
    }).toString();

    try {
      const response = await fetch(`http://localhost:5000/api/jobs?${query}`);
      const data = await response.json();
      setJobs(data);
    } catch (err) {
      console.error("Filter error:", err);
    }
    setLoading(false);
  };

  return (
    <div className="page">
      <header className="page-header">
        <h1>Full-Time Career Opportunities</h1>
        <p>Verified job openings for freshers and experienced graduates</p>
      </header>

      {/* Filters Bar */}
      <div className="filters-bar">
        <div className="filter-item">
          <label>Target Batch</label>
          <select value={year} onChange={(e) => setYear(e.target.value)}>
            <option value="">All Years</option>
            <option value="2024">2024 Graduate</option>
            <option value="2025">2025 Graduate</option>
            <option value="2026">2026 Graduate</option>
          </select>
        </div>

        <div className="filter-item">
          <label>Branch</label>
          <select value={branch} onChange={(e) => setBranch(e.target.value)}>
            <option value="">All Branches</option>
            <option value="CSE">CSE / IT</option>
            <option value="ECE">ECE / EEE</option>
            <option value="MECH">Mechanical</option>
            <option value="CIVIL">Civil</option>
            <option value="AI/DS">AI & Data Science</option>
          </select>
        </div>

        <div className="filter-item">
          <label>Sector</label>
          <select value={category} onChange={(e) => setCategory(e.target.value)}>
            <option value="">All Sectors</option>
            <option value="Government">Government / PSU</option>
            <option value="Private">Private / Corporate</option>
          </select>
        </div>

        <button className="btn-search" onClick={applyFilter} disabled={loading}>
          {loading ? "Searching..." : "Apply Filter"}
        </button>
      </div>

      {/* Jobs Grid */}
      <div className="jobs-grid">
        {jobs.length > 0 ? (
          jobs.map((job) => (
            <div 
              className={`job-card ${job.category === 'Government' ? 'govt-highlight' : ''}`} 
              key={job.jobId}
            >
              {job.category === 'Government' && <span className="govt-badge">Official PSU</span>}
              
              <div className="card-body">
                <h3 className="job-title">{job.jobTitle}</h3>
                <h4 className="company-name">{job.companyName}</h4>
                
                <div className="job-meta">
                  <span>📍 {job.location || "Multiple Locations"}</span>
                  <span className="job-type-tag">{job.jobType}</span>
                </div>

                <div className="job-tags">
                  {/* Mapping the branches array from the scraper */}
                  {job.eligible_branches?.map((b) => (
                    <span key={b} className="branch-tag">{b}</span>
                  ))}
                </div>
              </div>

              <div className="card-footer">
                <span className="scraped-date">
                  Added: {new Date(job.scrapedAt).toLocaleDateString()}
                </span>
                <a 
                  href={job.applicationLink} 
                  target="_blank" 
                  rel="noreferrer" 
                  className="apply-link"
                >
                  Apply Now
                </a>
              </div>
            </div>
          ))
        ) : (
          !loading && <div className="empty-state">No jobs found matching these filters.</div>
        )}
      </div>
    </div>
  );
}

export default Jobs;
